<script setup lang="ts">import{reactive,ref}from'vue';import{useRouter}from'vue-router';import{NButton,NForm,NFormItem,NInput,useMessage}from'naive-ui';import{api,setToken}from'../api';import{currentUser}from'../state';const router=useRouter(),message=useMessage(),loading=ref(false),form=reactive({username:'',password:''});async function submit(){loading.value=true;try{const data:any=await api.post('/auth/login',form);setToken(data.access_token);currentUser.value=data.user;router.push('/')}catch(e:any){message.error(e.message)}finally{loading.value=false}}</script>
<template><div class="login"><section class="login-art"><div><h1>NetUpDown</h1><p>让每一次发布，都清晰、可靠、触手可及。</p></div></section><section class="login-box"><div class="login-card"><span style="color:#4f6df5">管理控制台</span><h2>欢迎回来</h2><p style="color:#8b93a1">登录后管理应用、版本和下载来源。</p><n-form size="large" @submit.prevent="submit"><n-form-item label="用户名"><n-input v-model:value="form.username" autofocus/></n-form-item><n-form-item label="密码"><n-input v-model:value="form.password" type="password" show-password-on="click" @keyup.enter="submit"/></n-form-item><n-button block type="primary" :loading="loading" @click="submit">登录</n-button></n-form></div></section></div></template>
